python3 - \""'$task_tmp/bing.html" <<'"'PY'
import html, sys
from html.parser import HTMLParser
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_algo=False; self.in_h2=False; self.in_a=False; self.href=''; self.title=[]; self.text=[]; self.depth=0
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag=='li' and 'b_algo' in d.get('class','').split(): self.in_algo=True; self.depth=1; self.title=[]; self.text=[]; self.href=''
        elif self.in_algo:
            self.depth += 1
            if tag=='h2': self.in_h2=True
            if tag=='a' and self.in_h2 and not self.in_a: self.in_a=True; self.href=d.get('href','')
    def handle_endtag(self, tag):
        if self.in_algo:
            if tag=='a' and self.in_a: self.in_a=False
            if tag=='h2': self.in_h2=False
            self.depth -= 1
            if tag=='li' and self.depth==0:
                print('TITLE:', ''.join(self.title).strip())
                print('URL:', html.unescape(self.href))
                print('TEXT:', ' '.join(''.join(self.text).split())[:600])
                print()
                self.in_algo=False
    def handle_data(self, data):
        if self.in_algo:
            if self.in_a and self.in_h2: self.title.append(data)
            self.text.append(data)
p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
PY"

